'use strict';
/* Presentation layer shared by every view: the Business / Technical selector and deterministic business wording.
 *
 * Both ways of looking at the SAME data are rendered into the DOM; the selector only flips `body[data-mode]` and CSS hides
 * the other half. So switching never refetches, never creates a job or a model call, never loses a form, a selected node or a
 * waiting job, and Business/Technical can never show different values, permissions or snapshots.
 *
 * Wording here is a deterministic formatter (numbers, units, scope, state phrases). It is NOT AI. Text generated by a model
 * (summaries, suggestions) is shown separately and labelled as such; it is always inserted as text, never as HTML.
 * Nothing in this file touches localStorage/sessionStorage: the chosen view is kept in memory and in the URL (mode=technical). */
(function () {
  const {el} = App;

  // ------------------------------------------------------------------ view selector
  const MODES = ['business', 'technical'];
  App.mode = 'business';
  function applyMode() {
    document.body.dataset.mode = App.mode;
    for (const b of document.querySelectorAll('#mode-switch [data-mode]')) b.setAttribute('aria-pressed', String(b.dataset.mode === App.mode));
  }
  App.setMode = function (mode, fromUrl) {
    if (!MODES.includes(mode) || mode === App.mode) { if (MODES.includes(mode)) applyMode(); return; }
    App.mode = mode;
    applyMode();
    if (!fromUrl) App.setParams({mode: mode === 'technical' ? 'technical' : ''});
  };
  document.addEventListener('DOMContentLoaded', () => {
    applyMode();
    for (const b of document.querySelectorAll('#mode-switch [data-mode]')) b.addEventListener('click', () => App.setMode(b.dataset.mode));
  });
  /* Wrap a node so it shows only in one view. */
  App.T = node => { node.classList.add('tech-only'); return node; };
  App.B = node => { node.classList.add('biz-only'); return node; };
  /* Same data, two renderings: business wording and the technical text. */
  App.both = (biz, tech, tag) => el(tag || 'span', {}, App.B(el('span', {text: biz})), App.T(el('span', {text: tech})));

  // ------------------------------------------------------------------ copy / share
  const SHARE_KEYS = ['intent', 'draft', 'impact', 'simulation', 'proposal', 'review', 'approval', 'apply', 'query', 'chat'];
  /* The link a person hands to another account: current origin + the app route + only the saved-stage parameters. No token, no
   * cookie, no password; the server decides what the opener may see or do. */
  App.shareLink = function () {
    const r = App.parseHash();
    if (!r.ws) return '';
    const params = {};
    for (const k of SHARE_KEYS) if (r.params[k]) params[k] = r.params[k];
    return location.origin + location.pathname + App.hashFor(r.ws, r.view, r.sub, params);
  };
  /* Clipboard API first; when the browser refuses, the caller shows the text selected in a read-only box. */
  App.copyText = async function (text) {
    try {
      if (!navigator.clipboard || !navigator.clipboard.writeText) throw new Error('no clipboard');
      await navigator.clipboard.writeText(text);
      return true;
    } catch (_) { return false; }
  };

  // ------------------------------------------------------------------ deterministic business wording
  const num = v => {
    if (v === null || v === undefined || v === '') return '';
    const n = typeof v === 'number' ? v : Number(String(v).replace(/[ ,]/g, ''));
    return Number.isFinite(n) ? n.toLocaleString('en-US') : String(v);
  };
  const humanize = s => {
    const t = String(s || '').replace(/[_.]+/g, ' ').replace(/\s+/g, ' ').trim();
    return t ? t.charAt(0).toUpperCase() + t.slice(1) : '';
  };
  const isCode = u => /^[A-Z]{3}$/.test(String(u || ''));
  /* "1,000,000 JPY" (currency) or "1,000,000 net goods amount" (other unit); exact value only, no operator is invented. */
  const valueText = (value, unit, currency) => {
    const n = num(value);
    if (n === '') return 'not stated';
    const cur = isCode(currency) ? currency : (isCode(unit) ? unit : '');
    const other = unit && !isCode(unit) ? unit : '';
    return n + (cur ? ' ' + cur : '') + (other && !cur ? ' ' + other : '');
  };
  const scopeText = scope => {
    const e = Object.entries(scope && typeof scope === 'object' ? scope : {});
    return e.length ? e.map(([k, v]) => humanize(k).toLowerCase() + ': ' + (typeof v === 'string' ? v : JSON.stringify(v))).join('; ') : 'no scope stated';
  };
  /* Title of a rule from the extracted subject/predicate (generic humanising, nothing rule-specific). */
  const ruleTitle = (subject, predicate) => humanize(predicate) || humanize(subject) || 'Rule';
  const basename = p => String(p || '').split('/').pop();
  App.fmt = {num, humanize, valueText, scopeText, ruleTitle, basename, isCode};

  // Phrases for what a state means to a person (state names stay in the technical view and in data-state attributes).
  const JOB = {
    NONE: 'Not started', QUEUED: 'Waiting to run', RUNNING: 'Running', COMPLETED: 'Done', FAILED: 'Failed', CANCELLED: 'Cancelled',
    PENDING_APPROVAL: 'Waiting for a person with permission to allow this AI run', APPROVED: 'Allowed - waiting to run', PENDING: 'Waiting'};
  App.phrase = {
    job: s => JOB[s] || humanize(s),
    intent: s => ({DRAFT: 'Saved - waiting for an administrator to confirm the request', PARSED: 'Saved - waiting for an administrator to confirm the request',
      CONFIRMED: 'Confirmed', NEEDS_CLARIFICATION: 'More details are needed before it can be saved', STALE: 'Out of date'})[s] || humanize(s),
    draft: s => ({PARTIAL: 'Partly processed - some parts need a person', NEEDS_CONFIRMATION: 'Needs your confirmation first',
      COMPLETE: 'Complete'})[s] || humanize(s),
    gap: s => ({unresolved: 'Open', commented: 'Commented - not a decision', confirmed: 'Decided by a person'})[s] || humanize(s),
    node: s => ({'pending-confirmation': 'Extracted - not yet confirmed', confirmed: 'Confirmed by a person (source unchanged)',
      updated: 'Updated after a change was applied', stale: 'From an older revision', 'not-analysed': 'Not analysed', observed: 'Read from the file',
      proposed: 'Proposed link (not proven)', conflict: 'Conflict - needs a decision', 'scope-mismatch': 'Different scope - review',
      gap: 'Gap', ambiguity: 'Ambiguous', 'authority-decided': 'Authority chosen'})[s] || humanize(s),
    loop: s => ({PARTIAL: 'Partly done - some sources still need work', COMPLETE: 'Done', FAILED: 'Failed'})[s] || humanize(s),
  };
  /* A pill carrying BOTH wordings; data-state keeps the technical value for tests and tooling. */
  App.pill = function (state, bizText, opts) {
    const o = opts || {};
    return el('span', {class: 'pill' + (o.class ? ' ' + o.class : ''), testid: o.testid, data: Object.assign({state}, o.data || {})},
      App.B(el('span', {text: bizText})), App.T(el('span', {text: state})));
  };
  /* A technical field with a copy button; shown in the technical view only. */
  App.techField = function (label, value) {
    const v = typeof value === 'string' ? value : JSON.stringify(value);
    return App.T(el('div', {class: 'techfield'}, el('span', {class: 'muted', text: label + ': '}), el('code', {text: v}), ' ',
      el('button', {type: 'button', class: 'copy', 'aria-label': 'Copy ' + label, text: 'Copy', on: {click: ev => { App.copyText(v).then(ok => { ev.currentTarget.textContent = ok ? 'Copied' : 'Select and copy'; }); }}})));
  };
})();
